Definition zlength {X} (l : list X) : Z := Z.of_nat (length l).

(* [comment removed for export] *)
Definition SVC_STACK : Z := 144 + AINTRIN_STACK.

(* [comment removed for export] *)
Definition svc_obj (LF : list fframe) (m : mem) (bs : list byte) (A : Z) : Prop :=
  bs <> [] -> aapp A (zlength bs) /\ accessible m A (zlength bs) /\ shvis m A (A + zlength bs) /\ fsobj H LF A (zlength bs).

Definition svc_W (lo : Z) (sp : word) (dst n ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (dst, dst + n); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]%Z.

Definition svc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (sv dst src : Z) (bs : list byte) (rest : list cell) (LF : list fframe) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (zlength bs)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (svc_W lo sp dst (zlength bs) ff fp) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' sv (C8 (wz src) :: C8 (wz (zlength bs)) :: rest)
    /\ rw_cells asegs m' dst [CB (length bs) bs]
    /\ bytes_at asegs m' src bs
    /\ fresh_frame H LF 0 ff fp /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.      (* [comment removed for export] *)

Definition svc_stmt : Prop := forall (sv dst src : Z) (bs : list byte) (rest : list cell) (lo shi : Z) (junk : list byte) (LF : list fframe)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m sv (C8 (wz src) :: C8 (wz (zlength bs)) :: rest) ->
  bytes_at asegs m src bs ->
  rw_cells asegs m dst [CB (length bs) junk] ->
  (src + zlength bs <= dst \/ dst + zlength bs <= src) ->
  (dst + zlength bs <= sv \/ sv + Z.of_nat (cells_size (C8 (wz src) :: C8 (wz (zlength bs)) :: rest)) <= dst) ->
  stk asegs m lo (bv_unsigned sp) -> lo + SVC_STACK <= bv_unsigned sp -> aceil <= lo ->        (* [comment removed for export] *)
  bv_unsigned sp <= sv ->
  (dst + zlength bs <= lo \/ bv_unsigned sp <= dst) ->
  (src + zlength bs <= lo \/ bv_unsigned sp <= src) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi -> sv + 16 <= shi -> sv mod 8 = 0 ->
  zlength bs <= 2^40 ->                                                                         (* [comment removed for export] *)
  svc_obj LF m bs src -> svc_obj LF m bs dst ->
  evt asegs (svc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc sv dst src bs rest LF lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 sv) (Z_to_bv 64 dst) (Z_to_bv 64 (zlength bs)) (Z_to_bv 64 0) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SV_COPY) fc None m (seg_rom asegs)).
