  bytes_at asegs m1 src bs -> rw_cells asegs m1 dst [CB (length bs) junk] -> svc_obj LF m1 bs src -> svc_obj LF m1 bs dst ->
  (src + zlength bs <= slo \/ shi' <= src) -> (dst + zlength bs <= slo \/ shi' <= dst) ->
  munch (fs_W5 H slo shi' fp ff 0) m1 m2 -> wmono asegs m1 m2 -> SHAD m2 ff (poison_bytes 8 0) ->
